// MSB-first (Adafruit GFX) -> LSB-first (XBM, чего ждёт u8g2.drawXBM()) для одного байта
static uint8_t reverseBits(uint8_t b) {
  b = (b & 0xF0) >> 4 | (b & 0x0F) << 4;
  b = (b & 0xCC) >> 2 | (b & 0x33) << 2;
  b = (b & 0xAA) >> 1 | (b & 0x55) << 1;
  return b;
}

// Играет все кадры ровно один раз (не зацикливаясь) — вызывается один раз при каждом
// выключении Mute (см. remote_control.cpp, case IR_MUTE). Шлёт по SPI только тайлы под
// самой иконкой (не весь буфер, 1024 байта) — вне этой области буфер и так уже пустой
// (animateMuteFrame() всё это время ничего за пределами своей иконки не трогал), полная
// перерисовка тут не нужна вообще; следующий полноэкранный экран (drawMenu()/и т.п.,
// вызывается сразу после этой функции) сам всё равно всё перерисует целиком
void playUnmuteAnimation() {
  uint8_t buf[FRAME_BYTES];
  uint8_t tx = UNMUTE_ANIM_X / 8;
  uint8_t tw = (UNMUTE_ANIM_X + FRAME_WIDTH - 1) / 8 - tx + 1;
  uint8_t ty = UNMUTE_ANIM_Y / 8;
  uint8_t th = (UNMUTE_ANIM_Y + FRAME_HEIGHT - 1) / 8 - ty + 1;
  for (uint8_t f = 0; f < FRAME_COUNT; f++) {
    for (uint16_t i = 0; i < FRAME_BYTES; i++) {
      buf[i] = reverseBits(pgm_read_byte(&frames[f][i]));
    }
    u8g2.setDrawColor(0);
    u8g2.drawBox(UNMUTE_ANIM_X, UNMUTE_ANIM_Y, FRAME_WIDTH, FRAME_HEIGHT);
    u8g2.setDrawColor(1);
    u8g2.drawXBM(UNMUTE_ANIM_X, UNMUTE_ANIM_Y, FRAME_WIDTH, FRAME_HEIGHT, buf);
    u8g2.updateDisplayArea(tx, ty, tw, th);
    delay(UNMUTE_ANIM_FRAME_DELAY_MS);
  }
}
